// @ts-nocheck

import * as z from "zod";

export const aiGatewayEvaluationFallbackConditionSchema: z.ZodType = z.union([
	z.strictObject({
		confidenceBelow: z.number(),
		question: z.string().optional(),
	}),
	z.strictObject({
		probabilityBetween: z.array(z.number()).min(2).max(2),
		question: z.string().optional(),
	}),
	z.strictObject({
		get any() {
			return z.array(aiGatewayEvaluationFallbackConditionSchema);
		},
	}),
	z.strictObject({
		get all() {
			return z.array(aiGatewayEvaluationFallbackConditionSchema);
		},
	}),
	z.strictObject({
		get atLeast() {
			return z.object({
				conditions: z.array(aiGatewayEvaluationFallbackConditionSchema),
				count: z.number(),
			});
		},
	}),
]);

export const aiGatewayProviderOptionBagSchema = z
	.looseObject({})
	.describe("Arbitrary per-provider AI SDK options, keyed by gateway provider slug.");

export const aiGatewayRouterSelectorOptionBagSchema = z
	.looseObject({})
	.describe(
		"For kind=router: option slices keyed by selector name; each selector owns its slice's shape.",
	);

export const aiGatewayVirtualModelConfigSchema = z
	.object({
		allowFallbackFromFast: z
			.union([z.literal(false), z.literal(true)])
			.optional()
			.describe("Allow fallback from fast to standard providers on failure."),
		baseUrl: z
			.string()
			.optional()
			.describe("For kind=relay: URL the gateway forwards requests to as a transparent proxy."),
		byokCredentialIds: z
			.array(z.string())
			.optional()
			.describe("BYOK credential IDs allowed for this VMC."),
		caching: z.enum(["auto"]).optional().describe("Use caching if available."),
		createdAt: z.number().describe("Creation timestamp (epoch ms)."),
		createdBy: z.string().optional().describe("User or app id that created this VMC."),
		deleted: z
			.union([z.literal(false), z.literal(true)])
			.describe("Whether this VMC is soft-deleted."),
		description: z.string().optional().describe("Optional description for UI."),
		disallowPromptTraining: z
			.union([z.literal(false), z.literal(true)])
			.optional()
			.describe("Only use providers that will not train on your prompts."),
		displayName: z.string().optional().describe("Human-readable name for UI."),
		has: z
			.array(z.enum(["implicit-caching", "reasoning", "structured-output", "tool-use", "vision"]))
			.optional()
			.describe("Limit providers to those with these features."),
		hipaaCompliant: z
			.union([z.literal(false), z.literal(true)])
			.optional()
			.describe("Only use HIPAA-compliant providers."),
		inferenceRegion: z
			.object({
				geoRegion: z.string().optional().describe('Geo zone (e.g. "us", "eu").'),
				providerRegion: z.string().optional().describe("Provider-specific region identifier."),
				providers: z
					.record(
						z.string(),
						z.object({
							geoRegion: z.string().optional().describe('Geo zone (e.g. "us", "eu").'),
							providerRegion: z
								.string()
								.optional()
								.describe("Provider-specific region identifier."),
							scope: z
								.enum(["global", "specific", "zone"])
								.optional()
								.describe(
									"Pin scope: `specific` (one provider region), `zone` (geo zone), or `global`.",
								),
						}),
					)
					.optional()
					.describe("Per-provider region overrides keyed by provider slug."),
				scope: z
					.enum(["global", "specific", "zone"])
					.optional()
					.describe("Pin scope: `specific` (one provider region), `zone` (geo zone), or `global`."),
			})
			.optional()
			.describe("Region pinned on the VMC for system-credential routing (alias/router only)."),
		instanceId: z
			.string()
			.optional()
			.describe("The concrete model-provider instance this VMC resolves to."),
		kind: z.string().describe("VMC kind: alias, relay, or router."),
		get models() {
			return z
				.array(
					z.union([
						z.string(),
						z.strictObject({
							intelligence: z
								.number()
								.optional()
								.describe(
									"Highest task level the member handles, in [0, 1]. Read by the intelligence selector.",
								),
							slug: z.string(),
						}),
						z.strictObject({
							model: z.string(),
							when: aiGatewayEvaluationFallbackConditionSchema,
						}),
					]),
				)
				.optional()
				.describe(
					"For kind=router: ordered candidates, bare slugs/references or `{ slug, ...attributes }`. For kind=alias: ordered fallback model slugs, optionally led by one conditional `{ model, when }` entry, used when the primary model's answers match `when`.",
				);
		},
		modelSlug: z
			.string()
			.optional()
			.describe(
				'Canonical model slug this VMC maps to (e.g. "creator/model"). Not used by kind=router.',
			),
		observabilityTags: z
			.array(z.string())
			.optional()
			.describe("Observability tags attached to requests through this VMC."),
		ownerId: z.string().describe("Team (owner) that owns this VMC."),
		providerOnly: z
			.array(z.string())
			.optional()
			.describe("Restrict routing to only these providers."),
		providerOptions: z
			.record(z.string(), aiGatewayProviderOptionBagSchema)
			.optional()
			.describe("Arbitrary per-provider AI SDK options, keyed by gateway provider slug."),
		providerOrder: z
			.array(z.string())
			.optional()
			.describe("Ordered list of providers to try as fallbacks on failure."),
		providerTimeouts: z
			.object({
				byok: z.record(z.string(), z.number()).optional(),
			})
			.optional()
			.describe(
				"Per-request provider timeouts in ms, keyed by provider slug for BYOK credentials.",
			),
		selector: z
			.enum(["cost", "tps", "ttft"])
			.optional()
			.describe("For kind=router: how to order candidates. Absent means declared order."),
		selectorOptions: z
			.object({
				cost: aiGatewayRouterSelectorOptionBagSchema
					.optional()
					.describe(
						"For kind=router: option slices keyed by selector name; each selector owns its slice's shape.",
					),
				tps: aiGatewayRouterSelectorOptionBagSchema
					.optional()
					.describe(
						"For kind=router: option slices keyed by selector name; each selector owns its slice's shape.",
					),
				ttft: aiGatewayRouterSelectorOptionBagSchema
					.optional()
					.describe(
						"For kind=router: option slices keyed by selector name; each selector owns its slice's shape.",
					),
			})
			.optional()
			.describe(
				"For kind=router: option slices keyed by selector name; each selector owns its slice's shape.",
			),
		serviceTier: z
			.enum(["fast", "flex", "priority"])
			.optional()
			.describe("Service tier for providers that support it."),
		sort: z
			.enum(["cost", "latency", "price", "throughput", "tps", "ttft"])
			.optional()
			.describe("Rank eligible providers by an attribute."),
		speed: z.enum(["fast"]).optional().describe("Only use fastest providers with short timeouts."),
		status: z.string().describe("UI lifecycle status: draft, active, or archived."),
		updatedAt: z.number().describe("Last update timestamp (epoch ms)."),
		updatedBy: z.string().optional().describe("User or app id that last updated this VMC."),
		virtualModelSlug: z
			.string()
			.describe("Client-facing alias used as the model slug in Gateway calls."),
		visibility: z
			.string()
			.optional()
			.describe("Visibility in listings: public, internal, or stealth."),
		zeroDataRetention: z
			.union([z.literal(false), z.literal(true)])
			.optional()
			.describe("Only use providers with zero data retention."),
	})
	.describe("Active and archived router configurations owned by the authenticated team.");

