export const segmentSchema = z.object({
	createdAt: z.number(),
	createdBy: z.string().optional(),
	data: z.object({
		exclude: z
			.record(
				z.string(),
				z.record(
					z.string(),
					z.array(
						z.object({
							note: z.string().optional(),
							value: z.string(),
						}),
					),
				),
			)
			.optional(),
		include: z
			.record(
				z.string(),
				z.record(
					z.string(),
					z.array(
						z.object({
							note: z.string().optional(),
							value: z.string(),
						}),
					),
				),
			)
			.optional(),
		rules: z
			.array(
				z.object({
					conditions: z.array(
						z.object({
							cmp: z.enum([
								"!contains",
								"!endsWith",
								"!eq",
								"!ex",
								"!oneOf",
								"!regex",
								"!startsWith",
								"after",
								"before",
								"contains",
								"containsAllOf",
								"containsAnyOf",
								"containsNoneOf",
								"endsWith",
								"eq",
								"ex",
								"gt",
								"gte",
								"lt",
								"lte",
								"oneOf",
								"regex",
								"startsWith",
							]),
							cmpOptions: z
								.object({
									ignoreCase: z.union([z.literal(false), z.literal(true)]).optional(),
								})
								.optional(),
							lhs: z.discriminatedUnion("type", [
								z.strictObject({
									type: z.enum(["segment"]),
								}),
								z.strictObject({
									attribute: z.string(),
									kind: z.string(),
									type: z.enum(["entity"]),
								}),
							]),
							rhs: z
								.union([
									z.string(),
									z.number(),
									z.strictObject({
										items: z.array(
											z.union([
												z.strictObject({
													label: z.string().optional(),
													note: z.string().optional(),
													value: z.number(),
												}),
												z.strictObject({
													label: z.string().optional(),
													note: z.string().optional(),
													value: z.string(),
												}),
											]),
										),
										type: z.enum(["list", "list/inline"]),
									}),
									z.strictObject({
										flags: z.string(),
										pattern: z.string(),
										type: z.enum(["regex"]),
									}),
									z.union([z.literal(false), z.literal(true)]),
								])
								.optional(),
						}),
					),
					id: z.string(),
					outcome: z.discriminatedUnion("type", [
						z.strictObject({
							type: z.enum(["all"]),
						}),
						z.strictObject({
							base: z.object({
								attribute: z.string(),
								kind: z.string(),
								type: z.enum(["entity"]),
							}),
							passPromille: z.number(),
							type: z.enum(["split"]),
						}),
					]),
				}),
			)
			.optional(),
	}),
	description: z.string().optional(),
	hint: z.string(),
	id: z.string(),
	label: z.string(),
	projectId: z.string(),
	slug: z.string(),
	typeName: z.enum(["segment"]),
	updatedAt: z.number(),
	usedByFlags: z.array(z.string()).optional(),
	usedBySegments: z.array(z.string()).optional(),
	metadata: z
		.object({
			creator: z
				.object({
					id: z.string(),
					name: z.string(),
				})
				.optional(),
		})
		.optional(),
});

